  function renderNodeDetails(id) {
    const node = engine.model.nodes.find((item) => item.id === id);
    if (!node) return;
    const connected = engine.model.edges.filter((edge) => edge.source === id || edge.target === id);
    const list = element2("div", "connected-list");
    connected.forEach((edge) => {
      const otherId = edge.source === id ? edge.target : edge.source;
      const other = engine.model.nodes.find((item2) => item2.id === otherId);
      const item = element2("button", "connected-item", `${edge.source === id ? "\u2192" : "\u2190"} ${other?.label || otherId}`);
      item.type = "button";
      item.dataset.edgeId = edge.id;
      list.append(item);
    });
    elements.relationView.replaceChildren(
      element2("div", "inspector-eyebrow", "Vari\xE1vel selecionada"),
      element2("h3", "relation-title", node.label),
      element2("p", "relation-description", node.description || "Esta vari\xE1vel ainda n\xE3o possui descri\xE7\xE3o."),
      element2("div", "sidebar-section-title", "Rela\xE7\xF5es conectadas"),
      list
    );
    selectedNodeId = id;
    selectedEdgeId = null;
  }
